import { describe, expect, it } from 'vitest';
import edgeCasesJson from './sp_bef_edge_cases.json';
import {
  MILD_THETA_OFF_RATIO,
  SP_BEF_PARAMS,
  computeFrameReliability,
  computeGazeReliability,
  confusionLevel,
  piecewiseLinearInterp,
  predictLinearCalibratedBranch,
  spBefStep,
  type BranchConfig,
  type FusionConfig,
  type SpBefStepResult,
} from '../spBefCore';

// Shared with ml/tests/test_sp_bef.py and lms-api confusion_predictor_edge_test.go
// (generated by ml/export_sp_bef_edge_cases.py). NaN / Infinity are encoded as strings.
type EdgeNum = number | string;

interface EdgeCaseDoc {
  interp: { x: EdgeNum; xp: number[]; fp: number[]; expected: number }[];
  frame_reliability: { args: EdgeNum[]; expected: number }[];
  gaze_reliability: { args: EdgeNum[]; expected: number }[];
  branch: { cfg: BranchConfig; cases: { features: EdgeNum[]; expected: number[] }[] };
  step: {
    case_id: string;
    fusion: FusionConfig;
    args: Record<string, EdgeNum | boolean>;
    expected: SpBefStepResult;
  }[];
}

const doc = edgeCasesJson as unknown as EdgeCaseDoc;
const TOL = 1e-6;

function num(v: EdgeNum | boolean): number {
  if (v === 'NaN') return Number.NaN;
  if (v === 'Infinity') return Number.POSITIVE_INFINITY;
  if (v === '-Infinity') return Number.NEGATIVE_INFINITY;
  if (typeof v !== 'number') throw new Error(`unexpected edge value ${String(v)}`);
  return v;
}

describe('SP-BEF edge-case parity with Python and Go (sp_bef_edge_cases.json)', () => {
  it('piecewiseLinearInterp handles NaN (fp[0]), out-of-range and empty maps like Go', () => {
    for (const c of doc.interp) {
      expect(piecewiseLinearInterp(num(c.x), c.xp, c.fp)).toBeCloseTo(c.expected, 9);
    }
  });

  it('frame and gaze reliability sanitize NaN / Inf inputs', () => {
    for (const c of doc.frame_reliability) {
      const a = c.args.map(num);
      expect(Math.abs(computeFrameReliability(a[0], a[1], a[2], a[3], a[4]) - c.expected)).toBeLessThanOrEqual(TOL);
    }
    for (const c of doc.gaze_reliability) {
      const a = c.args.map(num);
      expect(Math.abs(computeGazeReliability(a[0], a[1], a[2], a[3]) - c.expected)).toBeLessThanOrEqual(TOL);
    }
  });

  it('linear branch ignores non-finite features and treats zero scale as 1', () => {
    for (const c of doc.branch.cases) {
      const out = predictLinearCalibratedBranch(c.features.map(num), doc.branch.cfg);
      [out.rawProb, out.calProb, out.llr].forEach((v, i) => {
        expect(Math.abs(v - c.expected[i])).toBeLessThanOrEqual(TOL);
      });
    }
  });

  it.each(doc.step.map((c) => [c.case_id, c] as const))('spBefStep %s matches Python and Go', (_id, c) => {
    const a = c.args;
    const out = spBefStep(
      num(a.prev_posterior),
      num(a.segment_prior),
      num(a.llr_face),
      num(a.r_face),
      num(a.llr_beh),
      num(a.r_beh),
      num(a.llr_quiz),
      num(a.r_quiz),
      c.fusion,
      num(a.prev_high_sec),
      Boolean(a.prev_intervening),
      num(a.cooldown_remaining_sec),
      num(a.dt_sec),
      num(a.llr_gaze),
      num(a.r_gaze),
    );
    expect(out.level).toBe(c.expected.level);
    expect(out.is_confused).toBe(c.expected.is_confused);
    expect(out.should_intervene).toBe(c.expected.should_intervene);
    const keys = [
      'prior_prob',
      'posterior_prob',
      'llr_face',
      'llr_quiz',
      'llr_gaze',
      'r_face',
      'r_quiz',
      'contrib_face',
      'contrib_quiz',
      'contrib_gaze',
      'segment_prior',
      'high_duration_sec',
      'cooldown_remaining_sec',
    ] as const;
    for (const k of keys) {
      expect(Number.isNaN(out[k])).toBe(false);
      expect(Math.abs(out[k] - c.expected[k])).toBeLessThanOrEqual(TOL);
    }
  });

  // Regression: with the shipped theta_off = 0.25 the former fixed mild floor (p >= 0.25) equalled theta_off.
  it('mild is reachable with the shipped params', () => {
    const { theta_on: on = 0, theta_off: off = 0 } = SP_BEF_PARAMS.fusion;
    expect(confusionLevel((MILD_THETA_OFF_RATIO * off + off) / 2, on, off, 1)).toBe('mild');
    expect(confusionLevel(MILD_THETA_OFF_RATIO * off - 1e-6, on, off, 1)).toBe('none');
    expect(confusionLevel(off, on, off, 1)).toBe('moderate');
    expect(confusionLevel(on, on, off, 1)).toBe('high');
    const step = spBefStep(0.2, 0.2, 0, 1, 0, 0, 0, 0, SP_BEF_PARAMS.fusion, 0, false, 0, 5);
    expect(step.posterior_prob).toBeLessThan(off);
    expect(step.level).toBe('mild');
  });
});
